function itemProduct(item){const p=byArt.get(normalizeArt(item.art));const variants=p?.stock?.variants||[],v=variants.find(v=>item.variant===v.label||item.variant.startsWith(v.label+' / ')),quantity=draft.items.filter(x=>normalizeArt(x.art)===normalizeArt(item.art)&&(!v||x.variant===v.label||x.variant.startsWith(v.label+' / '))).reduce((n,x)=>n+x.qty,0);return isListed(p)&&callEligibility(p,item.variant,quantity,draft.fields).ok?p:undefined;}
