function addProduct(){if(!activeProduct)return;if(missingCallDetails()){$('.product-call-setup').open=true;$('#product-call-vessel').focus();toast('Add your vessel, port and arrival day here first.');return;}const requested=Number($('#product-qty')?.value)||1,label=$('#product-stock-variant')?.value||'',eligible=callEligibility(activeProduct,label,requested,draft.fields);if(!eligible.ok){toast(eligible.text);return;}if(!isListed(activeProduct)){toast('This product is temporarily unavailable.');return;}if(availableVariants(activeProduct).length&&!availableVariants(activeProduct).some(v=>v.label===$('#product-stock-variant')?.value)){toast('Choose a size or colour.');$('#product-stock-variant')?.focus();return;}if(!orderableLine(activeProduct,$('#product-stock-variant')?.value||'')){toast('Choose an available size or colour.');return;}const qty=Number($('#product-qty').value);if(!Number.isInteger(qty)||qty<1||qty>999){toast('Choose a quantity from 1 to 999.');$('#product-qty').focus();return;}const note=$('#product-variant').value.trim(),variant=label?(note===label||note.startsWith(label+' / ')?note:label+(note?' / '+note:'')):note;let line=draft.items.find(x=>x.art===activeProduct.art&&x.variant===variant);if(!callEligibility(activeProduct,label,qty+draft.items.filter(x=>normalizeArt(x.art)===normalizeArt(activeProduct.art)&&(!label||x.variant===label||x.variant.startsWith(label+' / '))).reduce((n,x)=>n+x.qty,0),draft.fields).ok){toast('This quantity is not available for your call.');return;}if(line&&line.qty+qty>999){toast('Maximum 999 per line.');return;}if(line)line.qty+=qty;else draft.items.push({id:crypto.randomUUID?.()||String(Date.now())+Math.random(),art:activeProduct.art,qty,variant});save();renderProducts();renderList();closeDialog($('#product-dialog'));showAdded(activeProduct,qty);}
