function bindAccount(){const f=$('#account-form');if(!f||f.dataset.bound)return;f.dataset.bound='1';f.addEventListener('submit',async e=>{e.preventDefault();const email=f.email.value.trim().toLowerCase();if(!ordersUrl||!navigator.onLine){toast('Connect to sign in.');return;}const b=f.querySelector('button');b.disabled=true;b.textContent='Sending…';try{const j=await requestLogin(ordersUrl,email);toast(j.wait?'Link already sent. Check your inbox (and spam).':'Check your email ✓ Open the link on this phone to sign in.');b.textContent='Link sent ✓';}catch{b.disabled=false;b.textContent='Email me a sign-in link';toast('Could not send now. Check the email or try again.');}});}
