function openSpecial(){let d=$('#special-dialog');if(!d){d=document.createElement('dialog');d.id='special-dialog';d.innerHTML=`<div class="dialog-head"><div><span>CAN'T FIND IT?</span><h2>Special order</h2></div><button class="icon-btn close-dialog" aria-label="Close special order">×</button></div><form class="special-form" id="special-form"><p class="form-help">Tell us what you need. We look for it and send you a price before ordering. Once you accept the price and we order it, it cannot be cancelled.</p><label>Product *<input name="product" maxlength="150" required placeholder="e.g. Sony WH-1000XM5 headphones, black"></label><label>Quantity<input name="qty" type="number" min="1" max="999" value="1"></label><label>Budget (USD)<select name="budget"><option value="">Choose a range</option><option>Up to $50</option><option>$50–100</option><option>$100–200</option><option>$200–500</option><option>$500–1,000</option><option>More than $1,000</option></select></label><label>Description<textarea name="description" maxlength="600" rows="3" placeholder="Size, colour, model, anything that helps"></textarea></label><label>Link (if you have one)<input name="link" maxlength="400" placeholder="https://…"></label><p class="form-help" id="special-call"></p><p id="special-errors" class="storage-alert" hidden></p><button class="btn btn-send-order" type="submit" id="special-send">Send special order ✓</button></form>`;document.body.appendChild(d);d.addEventListener('close',()=>{if(!$('dialog[open]'))document.body.classList.remove('has-dialog');});$('#special-form').addEventListener('submit',submitSpecial);}const f=draft.fields;$('#special-call').textContent=f.vessel&&f.eta?`For ${f.vessel} · ${f.port} · arrival ${f.eta}. Contact: ${f.contact||'—'} ${f.phone||f.email||''}`:'Add your vessel, arrival day, name and contact in My list first.';openDialog('#special-dialog');}
