function keepInputs(container,render){
 const inputs=$$('input,select,textarea',container).map((el,index)=>({index,id:el.id,value:el.value,start:el.selectionStart,end:el.selectionEnd,focused:document.activeElement===el}));
 const scroll=container.closest('dialog'),top=scroll?.scrollTop;render();const fresh=$$('input,select,textarea',container);
 for(const state of inputs){const el=state.id?fresh.find(el=>el.id===state.id):fresh[state.index];if(!el)continue;if(el.tagName==='SELECT'&&!Array.from(el.options).some(o=>o.value===state.value)){const option=new Option(state.value+' · No longer listed',state.value);option.disabled=true;el.add(option);}el.value=state.value;if(state.focused){el.focus({preventScroll:true});try{el.setSelectionRange(state.start,state.end);}catch{}}}
 if(scroll)scroll.scrollTop=top;
}
