 if(activeProduct&&$('#product-dialog').open){const p=byArt.get(normalizeArt(activeProduct.art));if(p){const photo=activePhoto;activeProduct=p;keepInputs($('#product-detail'),()=>renderProductDetail(p));showPhoto(Math.min(photo,galleryImages(p).length-1));refreshSelectedStock();}else activeProduct=null;refreshSelectedStock();}
